 * `untrusted` (its content is suspect); a subagent/fork derivative is `derived`;
 * a clean top-level session is `trusted`.
 */
function trustFor(rec: CapturedSession): LessonTrust {
  if (!rec.secretScan.clean) return "untrusted";
  if (rec.subagentOf || rec.forkOf) return "derived";
  return "trusted";
}

