        if (id) sessionId = id;
        const c = asText(payload.cwd);
        if (c) cwd = c;

        const lineage = codexLineageFromMeta(payload);
        if (lineage?.isSubagent) {
          subagentOf = lineage.parentId;
          agentType = lineage.agentType;
        } else if (lineage) {
          forkOf = lineage.parentId;
          isFork = true;
        }
      }
      continue;
    }

    if (type === 'turn_context') {
      const m = asText(payload.model);
      if (m && !model) model = m;
      const c = asText(payload.cwd);
      if (c && !cwd) cwd = c;
      continue;
    }

    const channel = codexMessageChannel(obj);
    if (channel) turns[channel]++;

    const prompt = codexUserPromptFromLine(obj);
    if (prompt) {
