      // `item_completed` item's content is not): whatever becomes the
      // preview must have gone through the secret scan.
      scanParts.push(prompt);
      if (!firstUserPrompt) firstUserPrompt = prompt;
    }

    const pType = payload.type;
    if (pType === 'user_message' || pType === 'agent_message') {
      const msg = asText(payload.message);
      if (msg) scanParts.push(msg);
      continue;
    }
