    sessionId,
    runtime: 'codex',
    cwd,
    startedAt,
    endedAt,
    messageCount: turns.legacy || turns.item,
    model,
    firstUserPrompt,
    title,
    forkOf,
    subagentOf,
    agentType,
    isFork,
    scanText: scanParts.join('\n'),
