async function appendQuarantine(entry: QuarantineEntry): Promise<void> {
  let list: QuarantineEntry[] = [];
  try {
    const raw = await readFile(quarantinePath(), 'utf8');
    const parsed = QuarantineIndexSchema.safeParse(JSON.parse(raw));
    if (parsed.success) list = parsed.data;
  } catch {
    // No file yet.
  }
  // Replace any prior entry for the same file so the list does not grow on re-run.
  list = list.filter((e) => e.filePath !== entry.filePath);
  list.push(entry);
  await atomicWrite(quarantinePath(), JSON.stringify(list, null, 2));
}

